from datetime import datetime

from models import db
from models.model_uuid import uuid_str


class DeckAccessKey(db.Model):
    """Access / license keys generated by creators to distribute decks to students/classes."""

    __tablename__ = "deck_access_keys"

    id = db.Column(db.String(36), primary_key=True, default=uuid_str)
    deck_item_id = db.Column(
        db.String(36),
        db.ForeignKey("deck_marketplace_items.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    creator_user_id = db.Column(
        db.Integer,
        db.ForeignKey("users.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    key_code = db.Column(db.String(64), unique=True, nullable=False, index=True)
    label = db.Column(db.String(150), nullable=True)
    status = db.Column(
        db.Enum("active", "revoked", "expired", name="deck_access_key_status_enum", native_enum=False),
        nullable=False,
        default="active",
        index=True,
    )
    max_uses = db.Column(db.Integer, nullable=True)
    used_count = db.Column(db.Integer, nullable=False, default=0)
    expires_at = db.Column(db.DateTime, nullable=True, index=True)
    access_duration_days = db.Column(db.Integer, nullable=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow, nullable=False)
    updated_at = db.Column(
        db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow, nullable=False
    )

    deck_item = db.relationship("DeckMarketplaceItem", back_populates="access_keys")
    creator = db.relationship("User", foreign_keys=[creator_user_id])
    redemptions = db.relationship(
        "DeckAccessKeyRedemption",
        back_populates="access_key",
        cascade="all, delete-orphan",
        order_by="DeckAccessKeyRedemption.redeemed_at.desc()",
    )
